class ProductVariantModel { const ProductVariantModel({required this.id,required this.productId,this.size,this.color,this.imageId,required this.sku,this.price,this.salePrice,required this.quantity,required this.status}); final String id,productId,sku,status; final String? size,color,imageId; final double? price,salePrice; final int quantity; factory ProductVariantModel.fromJson(Map<String,dynamic> j)=>ProductVariantModel(id:j['id'].toString(),productId:j['productId'].toString(),size:j['size']?.toString(),color:j['color']?.toString(),imageId:j['imageId']?.toString(),sku:j['sku']?.toString()??'',price:(j['price'] as num?)?.toDouble(),salePrice:(j['salePrice'] as num?)?.toDouble(),quantity:(j['quantity'] as num?)?.toInt()??0,status:j['status']?.toString()??''); String get label=>[size,color].where((e)=>e != null && e.isNotEmpty).join(' / '); }